/* ═══════════ TIỆN ÍCH RIÊNG CỦA KHỐI 2 ═══════════ */
const Q = {};
/* chiếu toạ độ địa lý -> đơn vị bản đồ */
Q.V = (lat, lon) => [(lon - 99) * 46.5116, (24.5 - lat) * 46.5116 / 0.967046];
Q.T = (lat, lon) => [(lon + 180) * 2.777778, (90 - lat) * 2.777778];
/* mốc địa lý [vĩ độ, kinh độ] */
Q.D = {
  hanoi:[21.03,105.85], tphcm:[10.78,106.70], danang:[16.05,108.22],
  nhatrang:[12.25,109.19], trinuyen:[12.19,109.22], vinhluong:[12.33,109.19],
  mytho:[10.36,106.36], thudaumot:[10.98,106.65],
  juazeiro:[-9.42,-40.50], cayman:[19.31,-81.25], florida:[24.55,-81.78],
  chauphi:[2.0,21.0]
};
/* hộp ngắm [cx, cy, rộng] trong đơn vị bản đồ */
Q.K = {
  dongnama:[480, 440, 1820], vietnam:[320, 412, 1380], nam:[346, 596, 900],
  khanhhoa:[420, 520, 900], thegioi:[500, 250, 1020], myla:[300, 250, 560],
  phi:[530, 268, 430]
};
Q.noi = (a, b, u) => [lerp(a[0],b[0],u), lerp(a[1],b[1],u), lerp(a[2],b[2],u)];
Q.DAT = "#122A3A";

/* ---- nền bản đồ Đông Nam Á; sv.__vn là nhóm path Việt Nam để tô lại ---- */
Q.bdVN = function (sv, pre) {
  sv.innerHTML = "";
  gradR(sv, pre + "-bi", 470, 440, 900, [[0,"#123B4A"],[.52,"#0A2433"],[1,"#040E16"]]);
  el("rect", { x:-4000, y:-4000, width:12000, height:12000, fill:"url(#"+pre+"-bi)" }, sv);
  const g = el("g", {}, sv);
  const P = d => el("path", { d:d, fill:Q.DAT, stroke:"#1E3A4E", "stroke-width":1,
      "stroke-linejoin":"round", "vector-effect":"non-scaling-stroke" }, g);
  BD4.lang.forEach(P);
  sv.__vn = BD4.vn.map(P);
  sv.__g = g;
  return g;
};
/* ---- nền bản đồ thế giới; sv.__phi là nhóm path châu Phi ---- */
Q.bdTG = function (sv, pre) {
  sv.innerHTML = "";
  gradR(sv, pre + "-bi", 500, 250, 640, [[0,"#0F3242"],[.55,"#081E2B"],[1,"#030B12"]]);
  el("rect", { x:-4000, y:-4000, width:12000, height:12000, fill:"url(#"+pre+"-bi)" }, sv);
  const g = el("g", {}, sv);
  const P = d => el("path", { d:d, fill:"#1A3B4F", stroke:"#2E5873", "stroke-width":1,
      "vector-effect":"non-scaling-stroke" }, g);
  sv.__tg = BD4.tg.map(P);
  sv.__phi = BD4.phi.map(P);
  sv.__g = g;
  return g;
};
/* độ dày nét không đổi theo mức ngắm (viewBox co giãn) */
Q.net = (p, px, sv) => p.setAttribute("stroke-width",
  (px * (sv.__vb ? sv.__vb[2] : 1280) / 1280).toFixed(2));
Q.veDan = (p, u) => {
  p.setAttribute("pathLength", 1000);
  p.setAttribute("stroke-dasharray", "1000");
  p.setAttribute("stroke-dashoffset", (1000 * (1 - cl(u, 0, 1))).toFixed(1));
};
Q.to = (a, f, o) => a.forEach(p => { p.setAttribute("fill", f);
  p.style.opacity = (o === undefined ? 1 : o); });
/* quầng sáng trên bản đồ (quy chuẩn §F.3 cách 2) */
Q.quang = function (sv, pre, mau) {
  gradB(sv, pre + "-q", [[0, mau, .9], [.34, mau, .36], [1, mau, 0]]);
  return (p, r) => {
    const e = el("circle", { cx:p[0].toFixed(1), cy:p[1].toFixed(1), r:r || 34,
      fill:"url(#" + pre + "-q)", opacity:0 }, sv.__g);
    e.style.mixBlendMode = "screen";
    return e;
  };
};

/* bù lệch cho vật đặt tay bên trong một .lop đã bị nới ra 14% mỗi bên
   (cái bẫy 11.2 của hướng dẫn) */
Q.O = { x:179.2, y:100.8 };
Q.dat = (x, y, w, h) => "inset:auto;left:" + (x + Q.O.x).toFixed(1) + "px;top:" +
  (y + Q.O.y).toFixed(1) + "px;width:" + w + "px;height:" + h + "px";

/* ---- mảnh HTML dùng lại ---- */
Q.anh = (f, sau, loc, pos) =>
  '<div class="lop" data-sau="' + (sau === undefined ? .45 : sau) + '">' +
  '<img src="anh/' + f + '" alt="" style="object-position:' + (pos || "50% 50%") +
  ';filter:' + (loc || "contrast(1.08) saturate(.82) brightness(.6)") + '"></div>';
/* lớp tối góc — gradient CSS tĩnh, KHÔNG phải animation */
Q.toi = m =>
  '<div class="lop" data-sau="0.98"><div style="position:absolute;inset:-18%;' +
  'background:linear-gradient(rgba(10,26,38,.34),rgba(10,26,38,.34)),' +
  'radial-gradient(ellipse at 50% 46%,rgba(5,14,22,0) 26%,' +
  'rgba(5,14,22,.56) 70%,rgba(5,14,22,' + (m || ".92") + ') 100%)"></div></div>';
Q.ve = sau =>
  '<div class="lop" data-sau="' + (sau === undefined ? .8 : sau) +
  '"><svg class="ve" viewBox="0 0 1280 720" style="overflow:visible"></svg></div>';
Q.bdLop = () =>
  '<div class="lop" data-sau="0.5"><svg class="bd ve" viewBox="0 0 1280 720"></svg></div>';
Q.nenPhang = (a, b, goc) =>
  '<div class="lop" data-sau="0.08"><div style="position:absolute;inset:-18%;' +
  'background:linear-gradient(' + (goc || "165deg") + ',' + a + ' 0%,' + b + ' 100%)"></div></div>';
/* dòng nguồn ảnh, góc dưới phải — luôn đứng một mình (luật §8) */
Q.nguon = (id, s) =>
  '<div class="tx" id="' + id + '" style="left:auto;right:36px;top:678px;' +
  'font:400 13px/1.3 system-ui;letter-spacing:.01em;color:#5E7589;text-align:right">' + s + '</div>';
/* ghim địa danh: hộp trắng chữ đen + tam giác nhọn chỉ xuống (luật §F.4) */
Q.ghim = (id, ten) =>
  '<div class="tx" id="' + id + '" style="left:0;top:0;width:240px;text-align:center">' +
  '<div style="display:inline-block;background:#F6F8F5;color:#1C2A22;font:700 15px/1 system-ui;' +
  'letter-spacing:.07em;padding:6px 12px;border-radius:3px;white-space:nowrap">' + ten + '</div>' +
  '<div style="width:0;height:0;margin:0 auto;border:7px solid transparent;' +
  'border-top:9px solid #F6F8F5"></div></div>';
/* nhãn vùng lớn: chữ trần giãn, chỉ đặt TRONG vùng đã tô (luật §F.4) */
Q.nhanVung = (id, ten, mau) =>
  '<div class="tx" id="' + id + '" style="left:0;top:0;width:300px;text-align:center;' +
  'font:700 20px/1 system-ui;letter-spacing:.14em;color:' + (mau || "#8FA8BA") + '">' +
  ten + '</div>';
/* năm ở góc trên phải — đồng hồ của video (quy chuẩn §F.6) */
Q.nam = (id, n) =>
  '<div class="tx" id="' + id + '" style="left:auto;right:48px;top:36px;' +
  'font:800 46px/1 system-ui;font-variant-numeric:tabular-nums;letter-spacing:-.03em;' +
  'color:#C0392B">' + n + '</div>';

/* ---- sợi ADN xoắn kép, vẽ bằng hàm của t ---- */
Q.adn = function (p, x0, x1, y, bien, n, mauA, mauB) {
  const g = el("g", {}, p), A = [], B = [], T = [];
  for (let i = 0; i < n; i++) {
    T.push(el("line", { x1:0, y1:0, x2:0, y2:0, stroke:"#2A4D63",
      "stroke-width":3, "stroke-linecap":"round", opacity:0 }, g));
  }
  const sA = el("path", { d:"", fill:"none", stroke:mauA || "#6C8EBF",
    "stroke-width":6, "stroke-linecap":"round" }, g);
  const sB = el("path", { d:"", fill:"none", stroke:mauB || "#3F6A8C",
    "stroke-width":6, "stroke-linecap":"round" }, g);
  g.__ve = (pha, bd, kt) => {
    bd = bd === undefined ? 0 : bd; kt = kt === undefined ? 1 : kt;
    let da = "", db = "";
    for (let i = 0; i <= n * 3; i++) {
      const u = i / (n * 3), x = lerp(x0, x1, u), a = u * 11 + pha;
      da += (i ? "L" : "M") + x.toFixed(1) + "," + (y + Math.sin(a) * bien).toFixed(1);
      db += (i ? "L" : "M") + x.toFixed(1) + "," + (y - Math.sin(a) * bien).toFixed(1);
    }
    set(sA, { d:da }); set(sB, { d:db });
    T.forEach((e, i) => {
      const u = (i + .5) / n, x = lerp(x0, x1, u), a = u * 11 + pha;
      const yy = Math.sin(a) * bien;
      set(e, { x1:x.toFixed(1), y1:(y + yy).toFixed(1), x2:x.toFixed(1), y2:(y - yy).toFixed(1) });
      op(e, (u >= bd && u <= kt ? .85 * Math.abs(Math.cos(a)) : 0).toFixed(3));
    });
  };
  g.__A = sA; g.__B = sB; g.__T = T;
  return g;
};

