DANGKY({
  id: "k2c05", steps: 0,
  say: ["Theo một bài trên tạp chí PLOS về các bệnh nhiệt đới bị lãng quên, ở Juazeiro bên Brazil cách này làm quần thể muỗi giảm chín mươi lăm phần trăm."],
  html: Q.nenPhang("#0E2433", "#061018") + Q.ve(.72) +
        '<div class="hud">' +
        '<div class="tx" id="k2c05-s" style="left:72px;top:54px">' +
        '<span class="khung-so so" id="k2c05-n" style="font-size:150px;color:#C0392B">0</span>' +
        '</div>' +
        Q.nguon("k2c05-ng",
          "Carvalho DO và cộng sự, PLOS Negl Trop Dis 2015;9(7):e0003864 · CC BY 4.0") +
        '</div>',
  anim: root => {
    const V = root.querySelector("svg.ve"); V.innerHTML = "";
    const g = el("g", {}, V);
    el("path", { d:"M118 250 L118 636 L1180 636", fill:"none", stroke:"#2E5873",
      "stroke-width":3.4, "stroke-linecap":"round" }, g);
    /* hình dạng lấy theo đồ thị của bài: thả đều, quần thể tụt rồi giữ thấp */
    let d = "M140 288";
    for (let i = 1; i <= 52; i++) {
      const u = i / 52, x = 140 + i * 19.6;
      const y = 288 + 318 * (1 - Math.exp(-3.4 * u)) + 11 * Math.sin(i * 1.9) * (1 - u * .7);
      d += " L" + x.toFixed(1) + " " + y.toFixed(1);
    }
    const duong = el("path", { d:d, fill:"none", stroke:"#C0392B", "stroke-width":6,
      "stroke-linecap":"round", "stroke-linejoin":"round" }, g);
    const dau = el("circle", { cx:140, cy:288, r:9, fill:"#F6D7D2",
      stroke:"#0A1621", "stroke-width":3, opacity:0 }, g);
    /* Khoảng tin cậy 95% của bài báo: giảm 92,2–97,5 %, tức quần thể CÒN LẠI
       2,5–7,8 %. Ngoặc gắn đúng vào đầu mút đường, dùng chính hệ toạ độ của
       đường (y = 606 - 3,18 x % còn lại) — không nội suy thêm độ chính xác nào. */
    const Y = p => 606 - 3.18 * p;             /* 0 % -> 606 · 100 % -> 288 */
    const XC = 1159;
    const gC = el("g", { opacity:0 }, g);
    el("rect", { x:XC - 44, y:Y(7.8) - 14, width:88, height:(Y(2.5) - Y(7.8)) + 28,
      rx:6, fill:"#C0392B", opacity:.16 }, gC);
    el("line", { x1:XC, y1:Y(7.8), x2:XC, y2:Y(2.5), stroke:"#F0C8C2",
      "stroke-width":7, "stroke-linecap":"round" }, gC);
    el("line", { x1:XC - 34, y1:Y(2.5), x2:XC + 34, y2:Y(2.5), stroke:"#F0C8C2",
      "stroke-width":7, "stroke-linecap":"round" }, gC);
    el("line", { x1:XC - 34, y1:Y(7.8), x2:XC + 34, y2:Y(7.8), stroke:"#F0C8C2",
      "stroke-width":7, "stroke-linecap":"round" }, gC);
    el("circle", { cx:XC, cy:Y(5), r:11, fill:"#C0392B", stroke:"#F0C8C2",
      "stroke-width":3.4 }, gC);
    return c => {
      const u = ezo(cl(c.t / 2.6, 0, 1));
      Q.veDan(duong, u);
      const L = duong.getTotalLength();
      const p = duong.getPointAtLength(L * Math.max(.002, u));
      set(dau, { cx:p.x.toFixed(1), cy:p.y.toFixed(1) });
      op(dau, ez(c.t / .35));
      txt("k2c05-n", soVN(95 * ezo(c.t / 2.4)) + "%");
      kh("k2c05-s", c.t, .5, 1e9);
      op(gC, ez((c.t - 2.4) / .5).toFixed(3));
      kh("k2c05-ng", c.t, 2.9, 1e9);
    };
  }
});

/* ---- k2c06 · bản đồ thế giới: Cayman và Florida sáng lên ---- */
DANGKY({
  id: "k2c06", steps: 0,
  say: ["Nó cũng đã được thả ở quần đảo Cayman và ở Florida."],
  html: Q.bdLop() + '<div class="hud">' +
        Q.ghim("k2c06-cm", "CAYMAN") + Q.ghim("k2c06-fl", "FLORIDA") + '</div>',
  anim: root => {
    const sv = root.querySelector("svg.bd"); Q.bdTG(sv, "k2c06");
    const mk = Q.quang(sv, "k2c06", "#C0392B");
    const pc = Q.T(Q.D.cayman[0], Q.D.cayman[1]);
    const pf = Q.T(Q.D.florida[0], Q.D.florida[1]);
    const pj = Q.T(Q.D.juazeiro[0], Q.D.juazeiro[1]);
    const qj = mk(pj, 16), qc = mk(pc, 13), qf = mk(pf, 13);
    return c => {
      const u = ez(c.u);
      ngam(sv, lerp(300,296,u) + 2 * Math.sin(c.t * .3), lerp(248,242,u),
           lerp(372,326,u) * (1 + .01 * Math.sin(c.t * .24)));
      op(qj, (.45 * (.7 + .3 * Math.sin(c.t * 1.7))).toFixed(3));
      op(qc, (ez(c.t / .5) * (.8 + .2 * Math.sin(c.t * 2.2))).toFixed(3));
      op(qf, (ez((c.t - .55) / .5) * (.8 + .2 * Math.sin(c.t * 2.4 + 1))).toFixed(3));
      ghim("k2c06-cm", sv, pc, -120, 20);
      ghim("k2c06-fl", sv, pf, -232, 18);
      kh("k2c06-cm", c.t, .6, 1e9);
      kh("k2c06-fl", c.t, 1.05, 1e9);
    };
  }
});

