/* ---- k2c14 · di truyền công bằng: bố một nửa, mẹ một nửa ---- */
DANGKY({
  id: "k2c14", steps: 0,
  say: ["Di truyền bình thường chơi rất công bằng: bố một nửa, mẹ một nửa, mỗi gen có đúng năm mươi phần trăm cơ hội đi tiếp."],
  html: Q.nenPhang("#102434", "#061019") + Q.ve(.78),
  anim: root => {
    const V = root.querySelector("svg.ve"); V.innerHTML = "";
    const g = el("g", {}, V);
    /* hai hàng 10 ô: trên xanh (bố), dưới xám (mẹ); hàng dưới cùng trộn 5–5 */
    const o = [], W = 88, GAP = 18, X0 = 118;
    const hang = (y, n, mau) => {
      const a = [];
      for (let i = 0; i < n; i++)
        a.push(el("rect", { x:X0 + i * (W + GAP), y:y, width:W, height:W, rx:6,
          fill:mau, opacity:0 }, g));
      return a;
    };
    const bo = hang(112, 10, "#6C8EBF");
    const me = hang(248, 10, "#5E7589");
    const vach = el("path", { d:"M118 420 L1162 420", fill:"none", stroke:"#44637A",
      "stroke-width":3.4, "stroke-linecap":"round" }, g);
    const con = hang(498, 10, "#102434");
    return c => {
      cam(root, { t:c.t, x:lerp(-10,10,ez(c.u)), y:0, z:lerp(1.02,1.07,ez(c.u)) });
      bo.forEach((e, i) => op(e, ez((c.t - .15 - i * .035) / .3)));
      me.forEach((e, i) => op(e, ez((c.t - .35 - i * .035) / .3)));
      con.forEach((e, i) => {
        const s = c.t - .85 - i * .06;
        e.setAttribute("fill", i % 2 ? "#5E7589" : "#6C8EBF");
        op(e, ez(s / .3));
        set(e, { y:(498 - 18 * (1 - ez(s / .4))).toFixed(1) });
      });
      Q.veDan(vach, ezo((c.t - .7) / .7));
    };
  }
});

