/* ---- k2c19 · cắt gen bên kia rồi dán chính nó vào chỗ vừa cắt ---- */
DANGKY({
  id: "k2c19", steps: 0,
  say: ["Ngay trong lúc thụ tinh, nó cắt đúng cái gen tương ứng bên phía kia rồi dán chính nó vào chỗ vừa cắt."],
  html: Q.anh("k2-aedes-dot.jpg", .2, "contrast(1.08) saturate(.28) brightness(.2)", "50% 46%") +
        Q.toi(".95") + Q.ve(.78),
  anim: root => {
    const V = root.querySelector("svg.ve"); V.innerHTML = "";
    const g = el("g", {}, V);
    /* hai nhiễm sắc thể nằm ngang: trên mang drive (đỏ), dưới là bản lành */
    const thanh = (y, mau) => el("rect", { x:200, y:y, width:880, height:54, rx:27,
      fill:mau, stroke:"#1E3A4E", "stroke-width":3 }, g);
    thanh(188, "#1B3346"); thanh(458, "#1B3346");
    const drive = el("rect", { x:552, y:188, width:176, height:54, rx:27, fill:"#C0392B" }, g);
    const lanh  = el("rect", { x:552, y:458, width:176, height:54, rx:27, fill:"#6C8EBF" }, g);
    const khe = el("rect", { x:552, y:458, width:176, height:54, rx:27, fill:"#07131C",
      opacity:0 }, g);
    const banSao = el("rect", { x:552, y:188, width:176, height:54, rx:27, fill:"#C0392B",
      opacity:0 }, g);
    const keo = el("path", { d:"M0 -46 L0 46", stroke:"#F0C8C2", "stroke-width":6,
      "stroke-linecap":"round", opacity:0 }, g);
    return c => {
      cam(root, { t:c.t, x:lerp(14,-12,ez(c.u)), y:0, z:lerp(1.02,1.09,ez(c.u)) });
      /* 1) kéo quét qua chỗ gen lành */
      const a = ez((c.t - .4) / .5);
      set(keo, { transform:"translate(640 485)" });
      op(keo, (a * (1 - ez((c.t - 1.5) / .4))).toFixed(3));
      /* 2) gen lành biến mất, để lại một khe trống */
      op(lanh, (1 - ez((c.t - 1.0) / .45)).toFixed(3));
      op(khe, ez((c.t - 1.0) / .45).toFixed(3));
      /* 3) bản sao của drive rơi xuống lấp khe */
      const v = ezo(cl((c.t - 1.6) / 1.1, 0, 1));
      set(banSao, { y:lerp(188, 458, v).toFixed(1) });
      op(banSao, ez((c.t - 1.6) / .3).toFixed(3));
      op(drive, 1);
    };
  }
});

