          canh.push({ e:el("path", { d:"M" + px.toFixed(1) + " " + (y - 136 + r + 8) +
            " L" + x.toFixed(1) + " " + (y - r - 6), fill:"none", stroke:"#53303A",
            "stroke-width":Math.max(1.2, 4 - k * .7) }, g), k:k });
