      cam(root, { t:c.t, x:lerp(10,-10,ez(c.u)), y:lerp(28,-30,ez(c.u)), z:lerp(1.1,1.0,ez(c.u)) });
      canh.forEach(o => Q.veDan(o.e, ezo((c.t - .35 - o.k * 1.05) / .7)));
