/* ---- CỘT SỐT XUẤT HUYẾT: dùng lại ở k2c29 → k2c31 ---- */
const SXH = [["2017", 184741], ["2022", 371000], ["2023", 172000],
             ["2024", 114906], ["2025", 184903], ["2026", 170684]];
Q.cotSXH = function (sv) {
  sv.innerHTML = "";
  const g = el("g", {}, sv), o = [];
  const X0 = 152, W = 128, GAP = 38, Y1 = 596, H = 436, MAX = 371000;
  el("line", { x1:120, y1:Y1, x2:1160, y2:Y1, stroke:"#1E3A4E", "stroke-width":3 }, g);
  SXH.forEach((d, i) => {
    const x = X0 + i * (W + GAP);
    const r = el("rect", { x:x, y:Y1, width:W, height:0, fill:"#2E5169" }, g);
    const t = el("text", { x:(x + W / 2).toFixed(0), y:Y1 + 34, "text-anchor":"middle",
      fill:"#5E7589", opacity:0 }, g);
    t.textContent = d[0];
    t.setAttribute("font-size", "22"); t.setAttribute("font-family", "system-ui");
    t.setAttribute("font-weight", "700"); t.setAttribute("letter-spacing", ".06em");
    o.push({ r:r, t:t, h:H * d[1] / MAX, x:x, w:W, y1:Y1 });
  });
  sv.__cot = o;
  return o;
};
Q.moCot = (o, u, mau) => {
  const h = o.h * cl(u, 0, 1);
  set(o.r, { y:(o.y1 - h).toFixed(1), height:h.toFixed(1) });
  if (mau) o.r.setAttribute("fill", mau);
  op(o.t, cl(u * 3, 0, 1).toFixed(2));
};

